import { StockReservationService } from '../../domain/inventory/StockReservationService';
import { Order } from '../../domain/order/Order';
import { OrderLine } from '../../domain/order/OrderLine';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { Quantity } from '../../domain/shared/Quantity';
import { OrderDto, toOrderDto } from '../dto/OrderDto';
import { PlaceOrderCommand } from '../dto/PlaceOrderCommand';
import { Clock } from '../ports/Clock';
import { IdGenerator } from '../ports/IdGenerator';
import { ProductQuantity, StockAllocationService } from '../services/StockAllocationService';

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly allocations: StockAllocationService,
    private readonly reservation: StockReservationService,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  execute(command: PlaceOrderCommand): OrderDto {
    const allocations = this.allocations.load(this.mergeLines(command));
    const lines = allocations.map(
      ({ product, quantity }) => new OrderLine(product.id, quantity, product.unitPrice),
    );
    const order = Order.place({
      id: this.ids.next(),
      customerId: command.customerId,
      lines,
      placedAt: this.clock.now(),
    });

    this.reservation.reserve(allocations);
    this.allocations.persist(allocations);
    this.orders.save(order);

    return toOrderDto(order);
  }

  /** Combines repeated lines for the same product so stock is checked against the full amount. */
  private mergeLines(command: PlaceOrderCommand): ProductQuantity[] {
    const merged = new Map<string, Quantity>();
    for (const line of command.lines) {
      const quantity = Quantity.of(line.quantity);
      const existing = merged.get(line.productId);
      merged.set(line.productId, existing ? existing.add(quantity) : quantity);
    }
    return [...merged].map(([productId, quantity]) => ({ productId, quantity }));
  }
}

