import { StockReservationService } from '../../domain/inventory/StockReservationService';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { OrderDto, toOrderDto } from '../dto/OrderDto';
import { Clock } from '../ports/Clock';
import { OrderLookupService } from '../services/OrderLookupService';
import { StockAllocationService } from '../services/StockAllocationService';

/** Ships an order; its reserved stock physically leaves the warehouse. */
export class ShipOrderUseCase {
  constructor(
    private readonly lookup: OrderLookupService,
    private readonly orders: OrderRepository,
    private readonly allocations: StockAllocationService,
    private readonly reservation: StockReservationService,
    private readonly clock: Clock,
  ) {}

  execute(orderId: string): OrderDto {
    const order = this.lookup.getById(orderId);
    const allocations = this.allocations.load(order.lines);

    order.ship(this.clock.now());
    this.reservation.commit(allocations);

    this.allocations.persist(allocations);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

